1	// Regression coverage for the atomicity of a FAILED policy-set publish. A
2	// batch submitted to replace the current version is all-or-nothing: when any
3	// policy in the set is invalid, the whole commit is rejected with
4	// ErrInvalidPolicySet and no prefix of the valid leading policies may take
5	// effect. These tests pin the complete failure contract from an organization
6	// with a live, authorizing version:
7	//
8	//   - the error is ErrInvalidPolicySet, never ErrVersionConflict, and no
9	//     usable new version number comes back;
10	//   - authorization afterwards is still decided by the pre-commit version,
11	//     with reasons, matched policy ids and the version all from the old set
12	//     and no hit identifier that exists only in the failed set;
13	//   - the current version, every published version's content and the
14	//     would-be next version's absence are unchanged;
15	//   - the failed commit appends no policy-change record and leaves the
16	//     existing records, the head sequence and the checkpoint fingerprint
17	//     bit-for-bit intact, while ordinary decisions made afterwards still
18	//     record exactly what was returned;
19	//   - resubmitting the corrected set against the pre-failure current version
20	//     then succeeds as the immediate next version, flips authorization, and
21	//     adds exactly one policy-change record for the full new set.
22	//
23	// Two invalid shapes are covered: a trailing policy whose scope contains
24	// consecutive slashes, and a trailing policy that reuses the identifier of
25	// an earlier policy in the SAME submitted set. The duplicate's other fields
26	// are all valid and differ from the first occurrence, so the collision
27	// cannot be silently eliminated by overwriting the earlier policy.
28	package darksafe
29	
30	import (
31		"errors"
32		"reflect"
33		"testing"
34	)
35	
36	const atomicOrg = "acme"
37	
38	// atomicV1 is the originally published set: the probe subject may read the
39	// ledger and is explicitly denied writes.
40	func atomicV1() []Policy {
41		return []Policy{
42			{ID: "v1-allow-read", Subject: "u1", Action: "read", Scope: "org/acme/ledger", Effect: EffectAllow},
43			{ID: "v1-deny-write", Subject: "u1", Action: "write", Scope: "org/acme/ledger", Effect: EffectDeny},
44		}
45	}
46	
47	// atomicCandidatePrefix is the valid leading part of the replacing batch: it
48	// flips the probe's outcomes (read denied, write allowed), so any partial
49	// application of the batch is observable in the post-failure decisions.
50	func atomicCandidatePrefix() []Policy {
51		return []Policy{
52			{ID: "v2-deny-read", Subject: "u1", Action: "read", Scope: "org/acme/ledger", Effect: EffectDeny},
53			{ID: "v2-allow-write", Subject: "u1", Action: "write", Scope: "org/acme/ledger", Effect: EffectAllow},
54		}
55	}
56	
57	// atomicInvalidTails are the rejected final policies, one per subtest.
58	func atomicInvalidTails() map[string]Policy {
59		return map[string]Policy{
60			"consecutive slashes in scope": {
61				ID: "v2-extra", Subject: "u1", Action: "read",
62				Scope: "org/acme//ledger", Effect: EffectAllow,
63			},
64			// Every field but the identifier is valid, and the content differs
65			// from the earlier "v2-deny-read" entry, so the duplicate is a real
66			// second policy that cannot be merged away.
67			"duplicate id within the set": {
68				ID: "v2-deny-read", Subject: "u1", Action: "write",
69				Scope: "org/acme/ledger", Effect: EffectDeny,
70			},
71		}
72	}
73	
74	// atomicFixedTail replaces the invalid final policy in the corrected
75	// resubmission: valid, and scoped to a different subject so it never
76	// interferes with the probe decisions pinned below.
77	func atomicFixedTail() Policy {
78		return Policy{ID: "v2-extra", Subject: "u2", Action: "read", Scope: "org/acme/ledger", Effect: EffectAllow}
79	}
80	
81	func atomicReadReq() OrgRequest {
82		return request(atomicOrg, "u1", "ledger-1", "org/acme/ledger", "read")
83	}
84	
85	func atomicWriteReq() OrgRequest {
86		return request(atomicOrg, "u1", "ledger-1", "org/acme/ledger", "write")
87	}
88	
89	// TestFailedPublishLeavesAuthorizationAndAuditUntouched runs the full
90	// failure-and-recovery contract for each invalid tail shape.
91	func TestFailedPublishLeavesAuthorizationAndAuditUntouched(t *testing.T) {
92		for name, badTail := range atomicInvalidTails() {
93			t.Run(name, func(t *testing.T) {
94				s := NewStore()
95				v1 := atomicV1()
96				if v, err := s.Publish(atomicOrg, 0, v1); err != nil || v != 1 {
97					t.Fatalf("publish v1 = %d, %v; want 1, nil", v, err)
98				}
99	
100				readReq, writeReq := atomicReadReq(), atomicWriteReq()
101				// The pre-commit authorization outcomes, explained entirely by v1.
102				wantRead := Decision{
103					Allowed: true, Reason: "matched allow policy",
104					Matched: []string{"v1-allow-read"}, Version: 1,
105				}
106				wantWrite := Decision{
107					Allowed: false, Reason: "matched deny policy",
108					Matched: []string{"v1-deny-write"}, Version: 1,
109				}
110				if d := s.Decide(atomicOrg, readReq); !reflect.DeepEqual(d, wantRead) {
111					t.Fatalf("baseline read = %+v, want %+v", d, wantRead)
112				}
113				if d := s.Decide(atomicOrg, writeReq); !reflect.DeepEqual(d, wantWrite) {
114					t.Fatalf("baseline write = %+v, want %+v", d, wantWrite)
115				}
116	
117				// Snapshot the audit state the failed commit must preserve:
118				// publish v1 (seq 1) and the two baseline decisions (seq 2, 3).
119				preRecs, preCP, err := s.AuditExport(atomicOrg, 0)
120				if err != nil {
121					t.Fatalf("AuditExport before failure: %v", err)
122				}
123				if len(preRecs) != 3 || preCP.EndSeq != 3 {
124					t.Fatalf("records before failure = %d, checkpoint %+v; want 3 records ending at seq 3",
125						len(preRecs), preCP)
126				}
127				if err := VerifyAudit(atomicOrg, preRecs, preCP); err != nil {
128					t.Fatalf("chain does not verify before failure: %v", err)
129				}
130	
131				// The failing commit: valid leading policies that would flip both
132				// outcomes, then the invalid final policy, submitted against the
133				// correct current version.
134				candidate := append(atomicCandidatePrefix(), badTail)
135				v, err := s.Publish(atomicOrg, 1, candidate)
136				if !errors.Is(err, ErrInvalidPolicySet) {
137					t.Fatalf("publish err = %v, want ErrInvalidPolicySet", err)
138				}
139				if errors.Is(err, ErrVersionConflict) {
140					t.Fatalf("publish err = %v must not be reported as a version conflict", err)
141				}
142				if v != 0 {
143					t.Fatalf("failed publish returned version %d; no usable new version may come back", v)
144				}
145	
146				// Version state is exactly as before the attempt.
147				if got := s.CurrentVersion(atomicOrg); got != 1 {
148					t.Fatalf("current version = %d, want 1 after failed publish", got)
149				}
150				gotV1, err := s.Policies(atomicOrg, 1)
151				if err != nil || !reflect.DeepEqual(gotV1, v1) {
152					t.Fatalf("Policies(v1) = %+v, %v; want the original set, nil", gotV1, err)
153				}
154				if _, err := s.Policies(atomicOrg, 2); !errors.Is(err, ErrVersionNotFound) {
155					t.Fatalf("version 2 exists after failed publish, err = %v; want ErrVersionNotFound", err)
156				}
157	
158				// The failed commit left no trace in the audit chain: the
159				// records, the head sequence and the checkpoint fingerprint are
160				// bit-for-bit the pre-attempt ones.
161				postRecs, postCP, err := s.AuditExport(atomicOrg, 0)
162				if err != nil {
163					t.Fatalf("AuditExport after failure: %v", err)
164				}
165				if postCP != preCP {
166					t.Fatalf("checkpoint changed after failed publish: %+v vs %+v", preCP, postCP)
167				}
168				if !reflect.DeepEqual(postRecs, preRecs) {
169					t.Fatalf("audit records changed after failed publish")
170				}
171				if err := VerifyAudit(atomicOrg, postRecs, postCP); err != nil {
172					t.Fatalf("chain does not verify after failed publish: %v", err)
173				}
174	
175				// Authorization is still decided by v1 alone: the explanations
176				// carry only v1's reasons, hit identifiers and version, never an
177				// identifier that exists only in the failed set.
178				gotRead := s.Decide(atomicOrg, readReq)
179				if !reflect.DeepEqual(gotRead, wantRead) {
180					t.Fatalf("read after failure = %+v, want %+v from v1", gotRead, wantRead)
181				}
182				gotWrite := s.Decide(atomicOrg, writeReq)
183				if !reflect.DeepEqual(gotWrite, wantWrite) {
184					t.Fatalf("write after failure = %+v, want %+v from v1", gotWrite, wantWrite)
185				}
186	
187				// Those observation decisions are still recorded under the
188				// existing rules, and each record persists exactly the decision
189				// that was returned, including its version.
190				decisions := drainAudit(t, s, atomicOrg, AuditDecision, "")
191				if len(decisions) != 4 {
192					t.Fatalf("decision records = %d, want 4", len(decisions))
193				}
194				for i, want := range []Decision{wantRead, wantWrite, gotRead, gotWrite} {
195					dr := decisions[i]
196					if dr.Seq != i+2 || !reflect.DeepEqual(dr.Decision.Decision, want) {
197						t.Fatalf("decision record %d = seq %d %+v, want seq %d storing %+v",
198							i, dr.Seq, dr.Decision, i+2, want)
199					}
200				}
201	
202				// Correct the invalid tail and resubmit the same batch against
203				// the pre-failure current version: it publishes as the immediate
204				// next version.
205				fixed := append(atomicCandidatePrefix(), atomicFixedTail())
206				v, err = s.Publish(atomicOrg, 1, fixed)
207				if err != nil || v != 2 {
208					t.Fatalf("corrected publish = %d, %v; want 2, nil", v, err)
209				}
210				if got := s.CurrentVersion(atomicOrg); got != 2 {
211					t.Fatalf("current version = %d, want 2 after corrected publish", got)
212				}
213	
214				// Authorization flips exactly as the new set dictates.
215				wantReadV2 := Decision{
216					Allowed: false, Reason: "matched deny policy",
217					Matched: []string{"v2-deny-read"}, Version: 2,
218				}
219				wantWriteV2 := Decision{
220					Allowed: true, Reason: "matched allow policy",
221					Matched: []string{"v2-allow-write"}, Version: 2,
222				}
223				if d := s.Decide(atomicOrg, readReq); !reflect.DeepEqual(d, wantReadV2) {
224					t.Fatalf("read after corrected publish = %+v, want %+v", d, wantReadV2)
225				}
226				if d := s.Decide(atomicOrg, writeReq); !reflect.DeepEqual(d, wantWriteV2) {
227					t.Fatalf("write after corrected publish = %+v, want %+v", d, wantWriteV2)
228				}
229	
230				// Exactly one policy-change record was added for the corrected
231				// commit, carrying the complete new set; the v1 record is intact.
232				changes := drainAudit(t, s, atomicOrg, AuditPolicyChange, "")
233				if len(changes) != 2 {
234					t.Fatalf("policy-change records = %d, want 2", len(changes))
235				}
236				if changes[0].Change.Version != 1 || !reflect.DeepEqual(changes[0].Change.Policies, v1) {
237					t.Fatalf("v1 change record altered: %+v", changes[0].Change)
238				}
239				chg := changes[1].Change
240				if chg.Version != 2 || chg.RolledBack || chg.SourceVersion != 0 {
241					t.Fatalf("new change record = %+v, want plain publish of version 2", chg)
242				}
243				if !reflect.DeepEqual(chg.Policies, fixed) {
244					t.Fatalf("new change policies = %+v, want the full corrected set %+v", chg.Policies, fixed)
245				}
246	
247				// The old version still serves its original content, and the
248				// final chain verifies end to end.
249				gotV1, err = s.Policies(atomicOrg, 1)
250				if err != nil || !reflect.DeepEqual(gotV1, v1) {
251					t.Fatalf("Policies(v1) after corrected publish = %+v, %v; want the original set", gotV1, err)
252				}
253				finalRecs, finalCP, err := s.AuditExport(atomicOrg, 0)
254				if err != nil {
255					t.Fatalf("final AuditExport: %v", err)
256				}
257				if err := VerifyAudit(atomicOrg, finalRecs, finalCP); err != nil {
258					t.Fatalf("final chain does not verify: %v", err)
259				}
260			})
261		}
262	}
