				t.Fatalf("baseline read = %+v, want %+v", d, wantRead)
			}
			if d := s.Decide(atomicOrg, writeReq); !reflect.DeepEqual(d, wantWrite) {
				t.Fatalf("baseline write = %+v, want %+v", d, wantWrite)
			}

