// Command publish_atomicity_example is the worked example for organizational
// policy publishing: why a failed replacing commit leaves the standing
// authorization completely untouched, and how versioning, decisions and audit
// sequences are three different numbers.
//
// Run with:
//
//	go run ./examples/publish_atomicity
//
// The program takes no arguments, writes no files, and works fully offline.
// It uses only the public Store API and the Go standard library, creates its
// own in-memory store and requests, and prints state transitions next to
// audit state, so version returned by Publish, version actually used by a
// later decision and audit sequence numbers never have to be inferred — they
// are shown as distinct fields.
//
// One organization (acme factory), one enabled subject (svc-billing) reading
// one resource (billing-2026) at scope acme/factory/billing; the subject and
// the resource both belong to the decision organization, the scope is legal,
// so access is decided entirely by published policies with the organization
// default-deny / deny-overrides rules.
//
// The steps:
//
//  1. Publish an allowing read policy as version 1; the identical read is
//     allowed with reason/matched/version all from version 1, and both the
//     publish and the decision leave their mark on the audit chain (seq 1
//     policy_change, seq 2 decision).
//  2. Submit a NEW COMPLETE SET meant to flip the read to deny — it carries
//     one valid deny policy plus one policy whose scope contains consecutive
//     slashes ("acme//factory/billing"). Validation runs before any state
//     change, so Publish returns ErrInvalidPolicySet, the valid deny policy
//     is never applied first, no version number is consumed and no policy
//     change record appears. Checkpoints export the chain state so the
//     fingerprint at seq 2 can be compared directly across the failure.
//  3. To observe the effect, Decide the same read again AFTER the failed
//     publish. This observation decision is its own separate Decide call: it
//     is still evaluated under version 1 (allow, v1 policy id, version 1) and
//     leaves a NEW decision record (seq 3) under the existing rules. That
//     record must not be counted as a change produced by the failed publish.
//  4. Fix the invalid policy (consecutive slashes removed) and resubmit the
//     whole set against the UNCHANGED current version 1: it becomes version
//     2. Publish replaces the whole set rather than appending: the v1 allow
//     policy is absent from the version-2 change record's complete set and
//     absent from the matched list of the now-denied read, which reports a
//     clear denial reason, the deny policy id and version 2. The old version
//     still serves its original content via Policies(org, 1).
//  5. Finally, demonstrate the other commit boundary with fully valid content
//     but a stale expected version: after version 2 exists, submitting against
//     expected 1 returns ErrVersionConflict, neither version content nor the
//     current version are overwritten, and no change record is left. Callers
//     must re-read CurrentVersion, reconcile content, and decide whether to
//     resubmit.
package main

import (
	"errors"
	"fmt"
	"os"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

const (
	org        = "acme factory"
	subjectID  = "svc-billing"
	resourceID = "billing-2026"
	scope      = "acme/factory/billing"
	actionRead = "read"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "publish atomicity example: failed:", err)
	os.Exit(1)
	}
}

func run() error {
	store := darksafe.NewStore()

	// The one request used throughout: subject org and resource org both
	// equal the decision organization, subject enabled, scope legal. Access
	// is decided solely by the org's published policies; the subject carries
	// no role at all.
	req := darksafe.OrgRequest{
		SubjectOrg:  org,
		ResourceOrg: org,
		Subject:     darksafe.Subject{ID: subjectID, Kind: "service"},
		Resource:    darksafe.Resource{ID: resourceID, Scope: scope},
		Action:      actionRead,
	}

	// ---- Step 1: publish an allowing policy set as version 1. ------------
	fmt.Println("step 1: publish allow-read policy set")
	v1Set := []darksafe.Policy{{
		ID:      "p-billing-read-allow",
		Subject: subjectID,
		Action:  actionRead,
		Scope:   scope,
		Effect:  darksafe.EffectAllow,
	}}
	publishedV1, err := store.Publish(org, 0, v1Set) // 0: never published
	if err != nil {
		return fmt.Errorf("publish v1: %w", err)
	}
	fmt.Printf("  Publish -> new version %d\n", publishedV1)
	printPolicySet(v1Set)

	d1 := store.Decide(org, req)
	fmt.Printf("  Decide  -> allowed=%v reason=%q matched=%q applied-version=%d\n",
		d1.Allowed, d1.Reason, d1.Matched, d1.Version)
	if !d1.Allowed || d1.Version != 1 || len(d1.Matched) != 1 || d1.Matched[0] != "p-billing-read-allow" {
		return fmt.Errorf("step 1 decision = %+v, want allow matched p-billing-read-allow at version 1", d1)
	}
	head1 := snapshotHead(store, "after publishing v1 and one allow decision")
	fmt.Println()

	// ---- Step 2: the failed replacing commit. ----------------------------
	fmt.Println("step 2: submit replacing set with an invalid policy (consecutive slashes in scope)")
	badSet := []darksafe.Policy{
		{
			ID:      "p-billing-read-deny", // valid on its own: flips read to deny
			Subject: subjectID,
			Action:  actionRead,
			Scope:   scope,
			Effect:  darksafe.EffectDeny,
		},
		{
			ID:      "p-billing-read-extra",
			Subject: subjectID,
			Action:  actionRead,
			Scope:   "acme//factory/billing", // consecutive slashes: illegal
			Effect:  darksafe.EffectAllow,
		},
	}
	printPolicySet(badSet)
	badVersion, err := store.Publish(org, publishedV1, badSet)
	fmt.Printf("  Publish -> returned version=%d err=%v\n", badVersion, err)
	if !errors.Is(err, darksafe.ErrInvalidPolicySet) {
		return fmt.Errorf("failed publish error = %v, want ErrInvalidPolicySet", err)
	}
	if errors.Is(err, darksafe.ErrVersionConflict) {
		return fmt.Errorf("failed publish error = %v must not be a version conflict", err)
	}
	if badVersion != 0 {
		return fmt.Errorf("failed publish returned version %d, want 0 (no usable version)", badVersion)
	}

	// The current version is still 1, the old set is intact and version 2
	// does not exist yet.
	if got := store.CurrentVersion(org); got != publishedV1 {
		return fmt.Errorf("current version = %d, want %d after failed publish", got, publishedV1)
	}
	if _, err := store.Policies(org, publishedV1+1); !errors.Is(err, darksafe.ErrVersionNotFound) {
		return fmt.Errorf("version %d exists after failed publish, err=%v", publishedV1+1, err)
	}
	// The failed publish adds no record and moves no checkpoint: the chain
	// head is bit-for-bit the one from after step 1.
	head2 := snapshotHead(store, "immediately after the failed publish")
	head2.mustEqual(head1)
	fmt.Println("  the failed publish consumed no version, changed no policies and added no audit record")
	fmt.Println()

	// ---- Step 3: the observation decision is a separate operation. -------
	fmt.Println("step 3: observe with the same read after the failed publish")
	dObs := store.Decide(org, req)
	fmt.Printf("  Decide  -> allowed=%v reason=%q matched=%q applied-version=%d\n",
		dObs.Allowed, dObs.Reason, dObs.Matched, dObs.Version)
	if dObs.Allowed != d1.Allowed || dObs.Reason != d1.Reason ||
		!equalStrings(dObs.Matched, d1.Matched) || dObs.Version != d1.Version {
		return fmt.Errorf("observation decision = %+v, want the same verdict as %+v", dObs, d1)
	}
	// The observation is a new record (seq 3); the failed publish is not the
	// reason it exists — ordinary Decide rules are.
	head3 := snapshotHead(store, "after one observation decision")
	if head3.endSeq != head1.endSeq+1 {
		return fmt.Errorf("chain head = %d, want %d after observation", head3.endSeq, head1.endSeq+1)
	}
	fmt.Printf("  observation is a separate %s: it leaves its own decision record (seq %d);\n",
		"Decide", head3.endSeq)
	fmt.Println("  the failed publish itself left none, so this record is not a change made by that failure")
	fmt.Println()

	// ---- Step 4: correct the bad policy and resubmit the whole set. ------
	fmt.Println("step 4: fix the invalid scope and resubmit the complete set against current version 1")
	fixedSet := []darksafe.Policy{
		{
			ID:      "p-billing-read-deny",
			Subject: subjectID,
			Action:  actionRead,
			Scope:   scope,
			Effect:  darksafe.EffectDeny,
		},
		{
			ID:      "p-billing-read-extra",
			Subject: subjectID,
			Action:  actionRead,
			Scope:   "acme/factory/billing/audit", // consecutive slashes gone
			Effect:  darksafe.EffectAllow,
		},
	}
	printPolicySet(fixedSet)
	publishedV2, err := store.Publish(org, store.CurrentVersion(org), fixedSet)
	if err != nil {
		return fmt.Errorf("corrected publish: %w", err)
	}
	fmt.Printf("  Publish -> new version %d (immediate successor of %d)\n", publishedV2, publishedV1)
	if publishedV2 != publishedV1+1 {
		return fmt.Errorf("new version = %d, want %d", publishedV2, publishedV1+1)
	}

	d2 := store.Decide(org, req)
	fmt.Printf("  Decide  -> allowed=%v reason=%q matched=%q applied-version=%d\n",
		d2.Allowed, d2.Reason, d2.Matched, d2.Version)
	if d2.Allowed || d2.Reason != "matched deny policy" ||
		!equalStrings(d2.Matched, []string{"p-billing-read-deny"}) || d2.Version != 2 {
		return fmt.Errorf("step 4 decision = %+v, want deny matched p-billing-read-deny at version 2", d2)
	}

	// A publish replaces the whole set — it never appends to the old set.
	// The v2 change record carries exactly the submitted set; the old allow
	// policy id appears nowhere in it.
	recs, _, err := store.AuditExport(org, 0)
	if err != nil {
		return fmt.Errorf("export after corrected publish: %w", err)
	}
	changeV2 := recs[len(recs)-1]
	if changeV2.Kind != darksafe.AuditPolicyChange || changeV2.Change.Version != 2 {
		return fmt.Errorf("last record = %+v, want policy_change for version 2", changeV2)
	}
	if !equalPolicyIDs(changeV2.Change.Policies, fixedSet) {
		return fmt.Errorf("v2 change record stores %v, want the full submitted set %v",
			policyIDs(changeV2.Change.Policies), policyIDs(fixedSet))
	}
	fmt.Printf("  version-2 change record stores the complete new set: %q\n",
		policyIDs(changeV2.Change.Policies))
	// History is immutable: the old version still returns its original
	// content.
	oldSet, err := store.Policies(org, publishedV1)
	if err != nil {
		return fmt.Errorf("query old version: %w", err)
	}
	fmt.Printf("  Policies(org, %d) still returns the original set: %q\n", publishedV1, policyIDs(oldSet))
	fmt.Println()

	// ---- Step 5: valid content, stale expected version. ------------------
	fmt.Println("step 5: submit valid content against a stale expected version")
	staleSet := []darksafe.Policy{{
		ID:      "p-billing-read-allow",
		Subject: subjectID,
		Action:  actionRead,
		Scope:   scope,
		Effect:  darksafe.EffectAllow,
	}}
	printPolicySet(staleSet)
	staleVersion, err := store.Publish(org, publishedV1, staleSet) // current is already 2
	fmt.Printf("  Publish -> returned version=%d err=%v\n", staleVersion, err)
	if !errors.Is(err, darksafe.ErrVersionConflict) {
		return fmt.Errorf("stale publish error = %v, want ErrVersionConflict", err)
	}
	if staleVersion != 0 {
		return fmt.Errorf("stale publish returned version %d, want 0", staleVersion)
	}
	// Current policy is untouched, and the stale attempt leaves no record.
	if got := store.CurrentVersion(org); got != publishedV2 {
		return fmt.Errorf("current version = %d, want %d after stale submit", got, publishedV2)
	}
	current, err := store.Policies(org, publishedV2)
	if err != nil || !equalPolicyIDs(current, fixedSet) {
		return fmt.Errorf("current set = %v, %v; want the fixed set unchanged", policyIDs(current), err)
	}
	fmt.Printf("  current version stays %d; reconcile against it before resubmitting\n", publishedV2)
	snapshotHead(store, "after the stale-expected submit").mustEqual(
		snapshotHead(store, "after the corrected publish"))

	return nil
}

// headState is the audit chain head: highest sequence and the fingerprint
// covering it, captured via a complete export so two snapshots can be
// compared bit-for-bit.
type headState struct {
	endSeq      int
	fingerprint string
	count       int
	label       string
}

func snapshotHead(store *darksafe.Store, label string) headState {
	records, cp, err := store.AuditExport(org, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "publish atomicity example: export for %q: %v\n", label, err)
		os.Exit(1)
	}
	fmt.Printf("  [audit] %-48s records=%d head-seq=%d head-fingerprint=%s\n",
		label, len(records), cp.EndSeq, cp.Fingerprint)
	return headState{endSeq: cp.EndSeq, fingerprint: cp.Fingerprint, count: len(records), label: label}
}

func (h headState) mustEqual(want headState) {
	if h.endSeq != want.endSeq || h.fingerprint != want.fingerprint || h.count != want.count {
		fmt.Fprintf(os.Stderr, "publish atomicity example: audit state for %q = %+v, want %+v\n",
			h.label, h, want)
		os.Exit(1)
	}
	fmt.Printf("  [audit] checkpoint unchanged vs %q: head-seq=%d fingerprint=%s\n",
		want.label, h.endSeq, h.fingerprint)
}

func printPolicySet(policies []darksafe.Policy) {
	for _, p := range packages(policies) {
		fmt.Printf("    policy id=%q subject=%q action=%q scope=%q effect=%q recursive=%v resource-id=%q\n",
			p.ID, p.Subject, p.Action, p.Scope, p.Effect, p.Recursive, p.ResourceID)
	}
}

// packages returns the policies unchanged; the indirection keeps the set
// listing grouped in one helper alongside policyIDs.
func packages(policies []darksafe.Policy) []darksafe.Policy { return policies }

func policyIDs(policies []darksafe.Policy) []string {
	ids := make([]string, len(policies))
	for i, p := range policies {
		ids[i] = p.ID
	}
	return ids
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func equalPolicyIDs(policies []darksafe.Policy, want []darksafe.Policy) bool {
	return equalStrings(policyIDs(policies), policyIDs(want))
}

